// Regenerate with pier's palette (D154); source revisions: testdata/README.md.
//
//	node --experimental-strip-types coding/interactive/testdata/regenerate.mjs ./pi --write
//
// The golden file is generated by running the upstream tree selector with Node
// (coding/interactive/testdata/tree_golden.txt). Both sides write the same
// session JSONL fixture and load it with their session manager, so the tree
// projection also verifies GetTree().

type treeCaseJSON struct {
	Width             int      `json:"width"`
	TerminalHeight    int      `json:"terminalHeight"`
	CurrentLeafID     *string  `json:"currentLeafId"`
	InitialSelectedID *string  `json:"initialSelectedId"`
	InitialFilterMode string   `json:"initialFilterMode"`
	Inputs            []string `json:"inputs"`
}

type treeCorpus struct {
	SessionJSONL string                  `json:"sessionJsonl"`
	Cases        map[string]treeCaseJSON `json:"cases"`
}

// projectTree serializes the tree like the upstream probe does.
func projectTree(nodes []*coding.SessionTreeNode) []any {
	result := make([]any, 0, len(nodes))
	for _, node := range nodes {
		var label any
		if node.HasLabel {
			label = node.Label
		}
		var labelTimestamp any
		if node.HasLabel && node.LabelTimestamp != "" {
			labelTimestamp = node.LabelTimestamp
		}
		var parentID any
		if node.Entry.ParentID != nil {
			parentID = *node.Entry.ParentID
		}
		result = append(result, map[string]any{
			"id":             node.Entry.ID,
			"parentId":       parentID,
			"type":           node.Entry.Type,
			"label":          label,
			"labelTimestamp": labelTimestamp,
			"children":       projectTree(node.Children),
		})
	}
	return result
}

// TestTreeSelectorAgainstUpstreamGolden replays the tree projection and the
// tree selector renders.
func TestTreeSelectorAgainstUpstreamGolden(t *testing.T) {
	SetCustomThemesDir(t.TempDir())
	SetRegisteredThemes(nil)
	SetTrueColorSupport(true)
	SetStyleColorsEnabled(true)
	InitTheme("dark", false)

	golden := loadGoldenFile(t, "testdata/tree_golden.txt")
	data, err := os.ReadFile("testdata/tree_corpus.json")
	if err != nil {
		t.Fatalf("read corpus: %v", err)
	}
	corpus := treeCorpus{}
	if err := json.Unmarshal(data, &corpus); err != nil {
		t.Fatalf("parse corpus: %v", err)
	}

	treeProbeSessionPath := filepath.Join(t.TempDir(), "session.jsonl")
	if err := os.WriteFile(treeProbeSessionPath, []byte(corpus.SessionJSONL), 0o644); err != nil {
		t.Fatalf("write session: %v", err)
	}

	appKeybindings := NewAppKeybindingsManager(nil, "")
	previous := tui.GetKeybindings()
	tui.SetKeybindings(appKeybindings.KeybindingsManager)
	defer tui.SetKeybindings(previous)

	// A fixed clock keeps the label timestamps deterministic. The fixture
	// timestamps are from a different year, so the rendered form only depends
	// on the local timezone (shared by both sides).
	fixedNow := time.Date(2026, 5, 1, 12, 0, 0, 0, time.UTC)

	for _, label := range sortedKeys(corpus.Cases) {
		spec := corpus.Cases[label]
		manager, err := coding.OpenSession(treeProbeSessionPath, "", "")
		if err != nil {
			t.Fatalf("open session: %v", err)
		}
		tree := manager.GetTree()
		checkGolden(t, golden, label+"-tree", projectTree(tree))

		terminalHeight := spec.TerminalHeight
		if terminalHeight == 0 {
			terminalHeight = 40
		}
		component := NewTreeSelectorComponent(tree, spec.CurrentLeafID, terminalHeight,
			func(string) {}, func() {}, TreeSelectorOptions{
				Now:               func() time.Time { return fixedNow },
				ScheduleTimer:     func(ms int, fn func()) {},
				InitialSelectedID: spec.InitialSelectedID,
				InitialFilterMode: spec.InitialFilterMode,
			})

		checkGolden(t, golden, label+"@"+itoa(spec.Width), normalizeRender(component.Render(spec.Width)))
		for index, input := range spec.Inputs {
			component.HandleInput(input)
			encoded, _ := json.Marshal(input)
			checkGolden(t, golden, label+"+"+itoa(index)+"+"+string(encoded)+"@"+itoa(spec.Width),
				normalizeRender(component.Render(spec.Width)))
		}
	}
}

// TestTreeSelectorHelpers covers the pure tree helpers.
func TestTreeSelectorHelpers(t *testing.T) {
	themes := []string{}
	_ = themes

	rows := []horizontalViewportRow{
		{Gutter: "  ", Body: "0123456789", AnchorCol: 0, BodyWidth: 10, IsSelected: true},
		{Gutter: "  ", Body: "abcdefghij", AnchorCol: 4, BodyWidth: 10},
	}
	lines := renderHorizontalViewport(rows, 8)
	if len(lines) != 2 {
		t.Fatalf("lines = %d", len(lines))
	}
	if tui.VisibleWidth(lines[0]) > 8 || tui.VisibleWidth(lines[1]) > 8 {
		t.Fatalf("width overflow: %q %q", lines[0], lines[1])
	}
	if lines[0] != "  012345\x1b[0m" {
		t.Fatalf("unpanned = %q", lines[0])
	}

	// Panning: a long selected row with a far anchor scrolls the body.
	longRows := []horizontalViewportRow{
		{Gutter: "> ", Body: "0123456789012345678901234567890123456789", AnchorCol: 30, BodyWidth: 40, IsSelected: true},
	}
	panned := renderHorizontalViewport(longRows, 20)
	if panned[0][:2] != "> " {
		t.Fatalf("gutter lost: %q", panned[0])
	}
	if tui.VisibleWidth(panned[0]) > 20 {
		t.Fatalf("panned overflow: %q", panned[0])
	}

	if got := compactRawKeys([]string{"up", "down"}); got != "up/down" {
		t.Fatalf("compactRawKeys = %q", got)
	}
	if got := compactRawKeys([]string{"ctrl+a", "ctrl+b"}); got != "ctrl+a/b" {
		t.Fatalf("compactRawKeys = %q", got)
	}
	if got := compactRawKeys([]string{"pageUp"}); got != "pageUp" {
		t.Fatalf("compactRawKeys = %q", got)
	}
	if got := replaceWholeWords("pgup/down pageUp pageDown"); got != "pgup/↓ pgup pgdn" {
		t.Fatalf("replaceWholeWords = %q", got)
	}
	if got := toggleFilterMode(FilterUserOnly, FilterUserOnly); got != FilterDefault {
		t.Fatalf("toggle = %q", got)
	}
	if got := toggleFilterMode(FilterDefault, FilterUserOnly); got != FilterUserOnly {
		t.Fatalf("toggle = %q", got)
	}
	if got := indexOfFilterMode(FilterLabeledOnly); got != 3 {
		t.Fatalf("index = %d", got)
	}
}

// TestTreeSelectorLabels checks the label editing flow.
func TestTreeSelectorLabels(t *testing.T) {
	SetCustomThemesDir(t.TempDir())
	SetRegisteredThemes(nil)
	SetTrueColorSupport(true)
	SetStyleColorsEnabled(true)
	InitTheme("dark", false)

	appKeybindings := NewAppKeybindingsManager(nil, "")
	previous := tui.GetKeybindings()
	tui.SetKeybindings(appKeybindings.KeybindingsManager)
	defer tui.SetKeybindings(previous)

	entry := coding.SessionEntry{Type: "message"}
	entry.ID = "a"
	entry.Message = json.RawMessage(`{"role":"user","content":"hello"}`)
	tree := []*coding.SessionTreeNode{{Entry: entry}}

	var changes []string
	component := NewTreeSelectorComponent(tree, nil, 20, func(string) {}, func() {}, TreeSelectorOptions{
		OnLabelChange: func(entryID string, label *string) {
			if label == nil {
				changes = append(changes, entryID+"=nil")
				return
			}
			changes = append(changes, entryID+"="+*label)
		},
		ScheduleTimer: func(ms int, fn func()) {},
	})
	list := component.GetTreeList()

	// Shift+L opens the label input.
	component.HandleInput("L")
	if component.labelInput == nil {
		t.Fatal("label input not shown")
	}
	// Type a label and submit.
	for _, char := range "keep" {
		component.HandleInput(string(char))
	}
	component.HandleInput("\r")
	if component.labelInput != nil {
		t.Fatal("label input not hidden")
	}
	if len(changes) != 1 || changes[0] != "a=keep" {
		t.Fatalf("changes = %v", changes)
	}
	if !list.flatNodes[0].Node.HasLabel || list.flatNodes[0].Node.Label != "keep" {
		t.Fatalf("label not applied: %+v", list.flatNodes[0].Node)
	}

	// Re-open, clear with forward deletes and submit: the label is removed.
	component.HandleInput("L")
	for range "keep" {
		component.HandleInput("\x1b[3~")
	}
	component.HandleInput("\r")
	if len(changes) != 2 || changes[1] != "a=nil" {
		t.Fatalf("changes = %v", changes)
	}
	if list.flatNodes[0].Node.HasLabel {
		t.Fatal("label not cleared")
	}

	// Escape cancels without changes.
	component.HandleInput("L")
	component.HandleInput("\x1b")
	if component.labelInput != nil {
		t.Fatal("label input not cancelled")
	}
	if len(changes) != 2 {
		t.Fatalf("changes = %v", changes)
	}
}

// TestTreeSelectorEmptyAutoCancel checks the empty-tree cancel timer.
func TestTreeSelectorEmptyAutoCancel(t *testing.T) {
	SetCustomThemesDir(t.TempDir())
	SetRegisteredThemes(nil)
	SetTrueColorSupport(true)
	SetStyleColorsEnabled(true)
	InitTheme("dark", false)

	var fired []func()
	canceled := false
	NewTreeSelectorComponent(nil, nil, 20, func(string) {}, func() { canceled = true }, TreeSelectorOptions{
		ScheduleTimer: func(ms int, fn func()) { fired = append(fired, fn) },
	})
	if len(fired) != 1 {
		t.Fatalf("timers = %d", len(fired))
	}
	fired[0]()
	if !canceled {
		t.Fatal("cancel not fired")
	}
}

// tree-selector.ts extracts content with String.slice (UTF-16 code units).
func TestTreeExtractContentTruncatesByUTF16Units(t *testing.T) {
	text := strings.Repeat("中", 250)
	content, err := json.Marshal([]map[string]any{{"type": "text", "text": text}})
	if err != nil {
		t.Fatal(err)
	}
	if got := (&TreeList{}).extractContent(content); got != strings.Repeat("中", 200) {
		t.Fatalf("extractContent = %q", got)
	}
}

// The tree tool label truncates like upstream's String.slice: UTF-16 code
// units, so a multi-byte command keeps 50 characters, not 50 bytes.
func TestTreeToolLabelTruncatesBashCommandByUTF16Units(t *testing.T) {
	command := strings.Repeat("中", 60)
	got := (&TreeList{}).formatToolCall("bash", map[string]any{"command": command})
	want := "[bash: " + strings.Repeat("中", 50) + "...]"
	if got != want {
		t.Fatalf("label = %q; want %q", got, want)
	}
}

// contextEditTree builds the minimal shape GetTree returns for a user message
// with one context_edit child.
func contextEditTree(replacement json.RawMessage) []*coding.SessionTreeNode {
	parentID := "m1"
	return []*coding.SessionTreeNode{{
		Entry: coding.SessionEntry{
			Type:             "message",
			SessionEntryBase: coding.SessionEntryBase{ID: "m1", Timestamp: "2026-05-01T12:00:00Z"},
			Message:          json.RawMessage(`{"role":"user","content":[{"type":"text","text":"hello"}]}`),
		},
		Children: []*coding.SessionTreeNode{{
			Entry: coding.SessionEntry{
				Type:             "context_edit",
				SessionEntryBase: coding.SessionEntryBase{ID: "e1", ParentID: &parentID, Timestamp: "2026-05-01T12:00:01Z"},
				TargetID:         "m1",
				Replacement:      replacement,
			},
		}},
	}}
}

// tree-selector.ts treats context_edit as a settings/bookkeeping entry, so the
// default filter hides it. The port omitted it from isSettingsEntry and showed
// an empty row.
func TestTreeSelectorHidesContextEditEntriesByDefault(t *testing.T) {
	InitTheme("dark", false)
	list := NewTreeList(contextEditTree(json.RawMessage("null")), nil, 40, nil, FilterDefault)
	rendered := coding.StripAnsi(strings.Join(list.Render(80), "\n"))
	if !strings.Contains(rendered, "(1/1)") {
		t.Fatalf("default filter should hide context_edit:\n%s", rendered)
	}
}

// tree-selector.ts renders context_edit as [context omit: id] or
// [context replace: id]; the port's display switch had no case, so the row was
// blank.
func TestTreeSelectorLabelsContextEditEntries(t *testing.T) {
	InitTheme("dark", false)
	omitted := coding.StripAnsi(strings.Join(
		NewTreeList(contextEditTree(json.RawMessage("null")), nil, 40, nil, FilterAll).Render(80), "\n"))
	if !strings.Contains(omitted, "[context omit: m1]") {
		t.Fatalf("missing omit label:\n%s", omitted)
	}
	replaced := coding.StripAnsi(strings.Join(
		NewTreeList(contextEditTree(json.RawMessage(`{"content":"x"}`)), nil, 40, nil, FilterAll).Render(80), "\n"))
	if !strings.Contains(replaced, "[context replace: m1]") {
		t.Fatalf("missing replace label:\n%s", replaced)
	}
}

// tree-selector.ts's searchable text includes "context edit <omit|replace>
// <targetId>"; the port's search switch had no case.
func TestTreeSelectorSearchesContextEditEntries(t *testing.T) {
	InitTheme("dark", false)
	list := NewTreeList(contextEditTree(json.RawMessage("null")), nil, 40, nil, FilterAll)
	list.searchQuery = "context edit omit"
	list.ApplyFilter()
	rendered := coding.StripAnsi(strings.Join(list.Render(80), "\n"))
	if !strings.Contains(rendered, "[context omit: m1]") {
		t.Fatalf("search did not match context_edit:\n%s", rendered)
	}
}

// customMessageNode builds a tree with one custom_message entry whose content is
// the given raw JSON.
func customMessageNode(content json.RawMessage) []*coding.SessionTreeNode {
	return []*coding.SessionTreeNode{{
		Entry: coding.SessionEntry{
			Type:             "custom_message",
			SessionEntryBase: coding.SessionEntryBase{ID: "c1", Timestamp: "2026-05-01T12:00:00Z"},
			CustomType:       "note",
			Content:          content,
		},
	}}
}

// tree-selector.ts renders a custom_message's full content (a string as-is, or
// its joined text blocks) with no length cap; the port went through
// extractContent, which slices to 200 UTF-16 units.
func TestTreeSelectorShowsFullCustomMessageContent(t *testing.T) {
	InitTheme("dark", false)
	content, err := json.Marshal(strings.Repeat("a", 250) + "TAIL")
	if err != nil {
		t.Fatal(err)
	}
	rendered := coding.StripAnsi(strings.Join(
		NewTreeList(customMessageNode(content), nil, 40, nil, FilterAll).Render(500), "\n"))
	if !strings.Contains(rendered, "TAIL") {
		t.Fatalf("custom_message display truncated the content:\n%s", rendered)
	}
}

// tree-selector.ts searches a custom_message string content in full (only
// content blocks go through extractContent); the port capped the string too, so
// a token past 200 units was unfindable.
func TestTreeSelectorSearchesFullCustomMessageString(t *testing.T) {
	InitTheme("dark", false)
	content, err := json.Marshal(strings.Repeat("a", 250) + "TAIL")
	if err != nil {
		t.Fatal(err)
	}
	list := NewTreeList(customMessageNode(content), nil, 40, nil, FilterAll)
	list.searchQuery = "tail"
	list.ApplyFilter()
	rendered := coding.StripAnsi(strings.Join(list.Render(500), "\n"))
	if !strings.Contains(rendered, "[note]: ") {
		t.Fatalf("search did not match the full custom_message string:\n%s", rendered)
	}
}
